import math

def tent_integral(x, c, r):
    if x<=c-r: return 0.0
    if x<c: return (x-c+r)**2/(2*r)
    if x<c+r: return r-(c+r-x)**2/(2*r)
    return r

def image(d, label):
    edges=[.5*j/d+.25 for j in range(d+1)]
    base=[2*d*(tent_integral(edges[j+1],.5,.25)-tent_integral(edges[j],.5,.25)) for j in range(d)]
    bump=[2*d*(tent_integral(edges[j+1],.3125,.03125)-tent_integral(edges[j],.3125,.03125)) for j in range(d)]
    return [[(base[j]+.5*label*bump[j])*base[k] for k in range(d)] for j in range(d)]

def warp(X,scale,offset):
    d=len(X)
    indices=[math.floor(d*(scale*(j+.5)/(2*d)+offset)) for j in range(2*d)]
    W=[X[j][k] if 0<=j<d and 0<=k<d else 0.0 for j in indices for k in indices]
    norm=math.sqrt(sum(x*x for x in W)/len(W))
    return [x/norm for x in W]

def distance(X,Y): return math.sqrt(sum((x-y)**2 for x,y in zip(X,Y))/len(X))

for d in (32,64,128):
    X0,X1=image(d,0),image(d,1)
    print({'d':d,'unwarped_normalized_distance':distance(warp(X0,1,0),warp(X1,1,0)),'wrong_inverse_normalized_distance':distance(warp(X0,.5,.25),warp(X1,.5,.25))})
labels=[0,1]
for predictions in ([0,1],[1,1]):
    print({'labels':labels,'predictions':predictions,'equation_27_objective':-sum(k*p for k,p in zip(labels,predictions))/2,'zero_one_risk':sum(k"'!=p for k,p in zip(labels,predictions))/2})
